import{_ as o,a as l,b as r,c as s,d as e}from"./chunks/workshop-modal-replenish.BFUqmCRb.js";import{_ as n,I as i,g as a,j as u}from"./chunks/framework.CjoWWfVe.js";const x=JSON.parse('{"title":"Мастерская (Активы)","description":"Учет оборудования, инструментов и расчет их износа в ОмниКрафт ЕРП. Трансформируем траты в инвестиции.","frontmatter":{"title":"Мастерская (Активы)","description":"Учет оборудования, инструментов и расчет их износа в ОмниКрафт ЕРП. Трансформируем траты в инвестиции.","order":4},"headers":[],"relativePath":"ru/docs/spaces/production/workshop.md","filePath":"ru/docs/spaces/production/workshop.md"}'),q={name:"ru/docs/spaces/production/workshop.md"};function g(d,t,c,h,p,k){return i(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="мастерская-учет-активов-и-оборудования" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg> Мастерская: Учет активов и оборудования <a class="header-anchor" href="#мастерская-учет-активов-и-оборудования" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z&quot;/&gt;&lt;/svg&gt; Мастерская: Учет активов и оборудования&quot;">​</a></h1><figure class="doc-image"><img src="'+o+'" alt="Главное окно вкладки «Мастерская»"><figcaption>Главное окно вкладки «Мастерская»</figcaption></figure><p>Вкладка <strong>«Мастерская»</strong> представляет собой реестр вашего производственного имущества. Это не просто инвентаризационный список предметов, находящихся в помещении. Данный раздел управляет материальными активами, которые формируют значительную часть стоимости вашего бизнеса (Капитала).</p><p>Здесь ведется учет станков, дорогостоящего инструмента, электроники, расходных материалов и недвижимости, используемой в рабочем процессе.</p><hr><h2 id="экономическии-смысл-трансформация-затрат-в-капитал" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3h12l4 6-10 13L2 9Z"></path><path d="M11 3 8 9l4 13"></path><path d="M13 3l3 6-4 13"></path><path d="M2 9h20"></path></svg> Экономический смысл: Трансформация затрат в капитал <a class="header-anchor" href="#экономическии-смысл-трансформация-затрат-в-капитал" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M6 3h12l4 6-10 13L2 9Z&quot;/&gt;&lt;path d=&quot;M11 3 8 9l4 13&quot;/&gt;&lt;path d=&quot;M13 3l3 6-4 13&quot;/&gt;&lt;path d=&quot;M2 9h20&quot;/&gt;&lt;/svg&gt; Экономический смысл: Трансформация затрат в капитал&quot;">​</a></h2><p>В профессиональном управленческом учете приобретение дорогостоящего оборудования рассматривается иначе, чем повседневные бытовые траты. ОмниКрафт ЕРП опирается на два базовых экономических правила:</p><ol><li><strong>Сохранение капитала при покупке.</strong> Приобретение лазерного гравера или муфельной печи не делает вас беднее. Вы переводите ценность из формы «свободные деньги» в форму «производственное оборудование». Капитал вашего бизнеса остается неизменным, меняется лишь его структура.</li><li><strong>Учет амортизации (износа) без сложной рутины.</strong> В отличие от промышленных учетных систем, требующих точного высчитывания отработанных машино-часов, ОмниКрафт ЕРП использует бережливый подход: <ul><li>Программа автоматически рассчитывает и выводит в панели статистики <strong>общую точную сумму износа всей мастерской за месяц</strong>.</li><li>Опираясь на эту величину и ваш средний объем производства, вы можете установить усредненный глобальный норматив накладных расходов в Настройках.</li><li>В Калькуляторе этот норматив можно регулировать коэффициентами для каждого изделия. Таким образом, стоимость оборудования постепенно окупается при продаже готовой продукции.</li></ul></li></ol><hr><h2 id="режимы-работы-имущество-и-расходники" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg> Режимы работы: Имущество и Расходники <a class="header-anchor" href="#режимы-работы-имущество-и-расходники" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;polygon points=&quot;12 2 2 7 12 12 22 7 12 2&quot;/&gt;&lt;polyline points=&quot;2 17 12 22 22 17&quot;/&gt;&lt;polyline points=&quot;2 12 12 17 22 12&quot;/&gt;&lt;/svg&gt; Режимы работы: Имущество и Расходники&quot;">​</a></h2><p>Интерфейс таблицы разделен на две независимые вкладки, переключение между которыми осуществляется в верхней панели. Каждая вкладка имеет собственные настройки видимости колонок и систему фильтров.</p><h3 id="_1-имущество" tabindex="-1">1. Имущество <a class="header-anchor" href="#_1-имущество" aria-label="Permalink to &quot;1. Имущество&quot;">​</a></h3><p>Основной реестр долгосрочных активов. Сюда заносятся станки, мебель и инструменты, которые служат долго. Для этих объектов обязательно указывается срок службы, на основе которого программа рассчитывает ежемесячную амортизацию и постепенное снижение их остаточной стоимости.</p><h3 id="_2-расходники" tabindex="-1">2. Расходники <a class="header-anchor" href="#_2-расходники" aria-label="Permalink to &quot;2. Расходники&quot;">​</a></h3><p>Реестр быстро изнашиваемых материалов и вспомогательных элементов (например, фрезы, сверла, профессиональная химия, кисти). Главное отличие расходников состоит в том, что они <strong>не амортизируются</strong>. Их стоимость сразу в полном объеме списывается в расходы бизнеса (в журнал движения денежных средств — ДДС) в момент приобретения. Для расходников не указывается срок службы, так как их ценность переносится на производство мгновенно.</p><hr><h2 id="практическое-руководство-с-чего-начать" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path></svg> Практическое руководство: С чего начать? <a class="header-anchor" href="#практическое-руководство-с-чего-начать" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z&quot;/&gt;&lt;path d=&quot;M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z&quot;/&gt;&lt;/svg&gt; Практическое руководство: С чего начать?&quot;">​</a></h2><p>При первичном заполнении базы данных часто возникают сомнения: какую дату указывать для старого оборудования, как оценивать подарки и какой срок службы выбрать.</p><p>Ниже приведена таблица-шпаргалка и разбор реальных производственных сценариев, которые помогут вам избежать ошибок и уверенно сформировать капитал вашей мастерской.</p><h3 id="шпаргалка-мастера-ориентиры-для-заполнения" tabindex="-1">Шпаргалка мастера (Ориентиры для заполнения) <a class="header-anchor" href="#шпаргалка-мастера-ориентиры-для-заполнения" aria-label="Permalink to &quot;Шпаргалка мастера (Ориентиры для заполнения)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Тип имущества</th><th style="text-align:left;">Пример из базы</th><th style="text-align:left;">Оценка стоимости</th><th style="text-align:left;">Срок службы</th><th style="text-align:left;">Режим</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Тяжелое оборудование</strong></td><td style="text-align:left;"><em>Промышленный тестомес для глины</em></td><td style="text-align:left;">Первоначальная (фактическая) цена</td><td style="text-align:left;"><code>10–15 лет</code></td><td style="text-align:left;">Имущество</td></tr><tr><td style="text-align:left;"><strong>Формы и приборы</strong></td><td style="text-align:left;"><em>Набор из 3-х стальных сферических форм</em></td><td style="text-align:left;">Фактическая цена покупки</td><td style="text-align:left;"><code>5–10 лет</code></td><td style="text-align:left;">Имущество</td></tr><tr><td style="text-align:left;"><strong>Вспомогательное имущество</strong></td><td style="text-align:left;"><em>Подаренная большая бочка для замеса грязи</em></td><td style="text-align:left;">Оценочная рыночная стоимость</td><td style="text-align:left;"><code>10 лет</code></td><td style="text-align:left;">Имущество (без затрат в ДДС)</td></tr><tr><td style="text-align:left;"><strong>Быстроизнашиваемые материалы</strong></td><td style="text-align:left;"><em>Масло-разделитель для форм</em></td><td style="text-align:left;">Цена закупки + доставка</td><td style="text-align:left;"><code>0</code></td><td style="text-align:left;">Расходник</td></tr></tbody></table><h3 id="разбор-жизненных-сценариев-кеисы" tabindex="-1">Разбор жизненных сценариев (Кейсы) <a class="header-anchor" href="#разбор-жизненных-сценариев-кеисы" aria-label="Permalink to &quot;Разбор жизненных сценариев (Кейсы)&quot;">​</a></h3><details class="faq-item"><summary class="faq-summary">Кейс А: Безвозмездное имущество, находки и подарки</summary><p><strong>Ситуация:</strong> Внесение «Набора ручных инструментов, доставшегося по наследству» (36 000 ₽) или «Металлических стеллажей для сушки, найденных на складе» (25 200 ₽).</p><p><strong>Решение:</strong></p><ul><li><strong>Дата оприходования:</strong> Текущая дата (или примерная дата получения).</li><li><strong>Начальная стоимость:</strong> 36 000 ₽ (оценочная рыночная стоимость на сегодняшний день).</li><li><strong>Срок службы:</strong> 10 лет.</li><li><strong>Опция «Без учёта затрат в ДДС»:</strong> Обязательно <strong>включена</strong>.</li></ul><p><strong>Экономический результат:</strong> Капитал мастерской увеличивается на 36 000 ₽ (активы бизнеса выросли), при этом операция <strong>не создает расхода в журнале ДДС</strong> и не изменяет денежный остаток мастерской, так как физической выплаты средств не происходило.</p></details><details class="faq-item"><summary class="faq-summary">Кейс Б: Закупка нового оборудования с логистическими издержками</summary><p><strong>Ситуация:</strong> Вы приобрели новый «Промышленный тестомес для глины» за 288 000 ₽ и оплатили транспортной компании 12 000 ₽ за его доставку.</p><p><strong>Решение:</strong></p><ul><li><strong>Дата оприходования:</strong> Дата фактической покупки.</li><li><strong>Начальная стоимость:</strong> 288 000 ₽.</li><li><strong>Доставка:</strong> 12 000 ₽.</li><li><strong>Срок службы:</strong> 15 лет.</li><li><strong>Опция «Без учёта затрат в ДДС»:</strong> Выключена.</li></ul><p><strong>Экономический результат:</strong> Программа автоматически списывает 300 000 ₽ в журнале ДДС (разделяя траты на статьи «Оборудование» и «Логистика»). Актив зачисляется на баланс мастерской стоимостью 300 000 ₽, и с этого дня запускается его планомерная амортизация.</p></details><details class="faq-item"><summary class="faq-summary">Кейс В: Приобретение расходных материалов</summary><p><strong>Ситуация:</strong> Закупка партии «Масла-разделителя для форм» (2 700 ₽) или «Прочных мешков для мусора» (2 250 ₽).</p><p><strong>Решение:</strong></p><ul><li><strong>Дата оприходования:</strong> Дата закупки.</li><li><strong>Начальная стоимость:</strong> 2 700 ₽.</li><li><strong>Опция «Расходник»:</strong> Обязательно <strong>включена</strong> (поле срока службы автоматически заблокируется).</li></ul><p><strong>Экономический результат:</strong> Полная сумма (2 700 ₽) мгновенно списывается в операционные расходы бизнеса в ДДС. Позиция появляется во вкладке «Расходники» и не формирует амортизационный износ, не перегружая балансовые расчеты имущества.</p></details><details class="faq-item"><summary class="faq-summary">Кейс Г: Историческое оборудование (куплено до внедрения программы)</summary><p><strong>Ситуация:</strong> Вы купили «Автоматическую соломорезку» 3 года назад за 99 000 ₽. Вы хотите внести её в систему сейчас.</p><p><strong>Решение:</strong></p><ul><li><strong>Дата оприходования:</strong> Историческая дата (выбрать в календаре примерный день покупки 3 года назад).</li><li><strong>Начальная стоимость:</strong> 99 000 ₽ (первоначальная цена покупки, даже если сейчас станок стоит дешевле).</li><li><strong>Срок службы:</strong> 10 лет (общий срок службы от даты покупки).</li><li><strong>Опция «Без учёта затрат в ДДС»:</strong> Выключена.</li></ul><p><strong>Экономический результат:</strong> Программа зафиксирует историческую инвестицию в 99 000 ₽ в ДДС. Затем она автоматически рассчитает амортизацию за прошедшие 3 года и выведет корректную остаточную стоимость (около 69 300 ₽) в текущий Капитал мастерской.</p></details><hr><h2 id="внесение-нового-актива" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M8 12h8"></path><path d="M12 8v8"></path></svg> Внесение нового актива <a class="header-anchor" href="#внесение-нового-актива" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;circle cx=&quot;12&quot; cy=&quot;12&quot; r=&quot;10&quot;/&gt;&lt;path d=&quot;M8 12h8&quot;/&gt;&lt;path d=&quot;M12 8v8&quot;/&gt;&lt;/svg&gt; Внесение нового актива&quot;">​</a></h2><p>Чтобы добавить новую позицию, нажмите кнопку <strong>«Внести актив»</strong> в верхней части экрана.</p><figure class="doc-image"><img src="'+l+'" alt="Модальное окно добавления нового актива"><figcaption>Модальное окно добавления нового актива</figcaption></figure><p>Программа использует принцип <strong>оценочной точки старта</strong>: если вы вносите старый инструмент, приобретенный до начала работы в ОмниКрафт ЕРП, просто оцените его так, как если бы продавали его сегодня, и укажите примерный оставшийся срок службы.</p><h3 id="основные-параметры" tabindex="-1">Основные параметры <a class="header-anchor" href="#основные-параметры" aria-label="Permalink to &quot;Основные параметры&quot;">​</a></h3><ul><li><strong>Название актива:</strong> Краткое и понятное наименование.</li><li><strong>Дата оприходования:</strong> Точный день поступления оборудования на баланс. По умолчанию подставляется текущая дата (сегодня), но с помощью встроенного календаря вы можете выбрать любое число в прошлом для восстановления исторического учета.</li><li><strong>Категория:</strong> Группа для структурирования и аналитики (например, Оборудование, Инструменты, Помещение).</li><li><strong>Начальная стоимость:</strong> Цена покупки (для новых вещей) или ваша оценка на сегодняшний день (для старых). Введенная сумма будет <strong>автоматически зафиксирована как расход в журнале ДДС</strong> (в категории «Оборудование и инструменты»), за исключением случаев, когда активирована опция «Без учёта затрат в ДДС».</li><li><strong>Доставка:</strong> Если доставка оборудования потребовала дополнительных расходов, укажите их здесь. Сумма будет автоматически зафиксирована в журнале ДДС в категории «Логистика».</li><li><strong>Срок службы (лет):</strong> Планируемое время эксплуатации. Автоматический расчет равномерного износа (амортизации) и текущей остаточной стоимости начинается строго от зафиксированной даты оприходования.</li></ul><h3 id="специальные-настроики-чекбоксы" tabindex="-1">Специальные настройки (Чекбоксы) <a class="header-anchor" href="#специальные-настроики-чекбоксы" aria-label="Permalink to &quot;Специальные настройки (Чекбоксы)&quot;">​</a></h3><p>Две опции в форме добавления позволяют точно настроить финансовую логику операции:</p><div class="tip custom-block"><p class="custom-block-title">Галочка «Расходник»</p><p>Активируйте её при внесении мелкого инструмента или химии. Программа заблокирует поле «Срок службы» и поместит позицию во вкладку «Расходники». Вся сумма покупки будет сразу списана в расходы.</p></div><div class="tip custom-block"><p class="custom-block-title">Галочка «Без учёта затрат в ДДС»</p><p>Используйте эту опцию, если инструмент был принесен из личного гаража, подарен или приобретен за счет целевого гранта (безвозмездное поступление). Оборудование будет зачислено на баланс бизнеса (увеличив ваш Капитал), но программа <strong>не спишет средства из кассы ДДС</strong>, поскольку фактической траты не происходило.</p></div><h3 id="дополнительные-параметры" tabindex="-1">Дополнительные параметры <a class="header-anchor" href="#дополнительные-параметры" aria-label="Permalink to &quot;Дополнительные параметры&quot;">​</a></h3><p>Блок раскрывается при нажатии на соответствующий заголовок внизу формы. В нем можно указать:</p><ul><li><strong>Инв. номер (Авто):</strong> Оставьте поле пустым, и система автоматически сгенерирует номер формата <code>ИНВ-XXXX</code> (или <code>INV-XXXX</code>).</li><li><strong>Локация:</strong> Физическое расположение объекта (конкретный стеллаж или помещение).</li><li><strong>Фотография:</strong> Вы можете прикрепить снимок инструмента. Программа автоматически сожмет изображение в современный формат WebP для экономии места на диске.</li><li><strong>Ссылка:</strong> Ссылка на магазин поставщика, спецификацию или инструкцию.</li><li><strong>Заметки / Комментарий:</strong> Произвольный текстовый блок для описания.</li></ul><hr><h2 id="жизненныи-цикл-активов-и-доступные-операции" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"></path><path d="M3 3v5h5"></path></svg> Жизненный цикл активов и доступные операции <a class="header-anchor" href="#жизненныи-цикл-активов-и-доступные-операции" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;path d=&quot;M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8&quot;/&gt;&lt;path d=&quot;M3 3v5h5&quot;/&gt;&lt;/svg&gt; Жизненный цикл активов и доступные операции&quot;">​</a></h2><p>В процессе работы оборудование требует обслуживания, переоценки или списания. Все операции доступны через кнопки действий в строках таблицы.</p><h3 id="паспорт-актива-интерактивная-карточка" tabindex="-1">Паспорт актива (Интерактивная карточка) <a class="header-anchor" href="#паспорт-актива-интерактивная-карточка" aria-label="Permalink to &quot;Паспорт актива (Интерактивная карточка)&quot;">​</a></h3><p>При нажатии на название любого актива открывается его подробный паспорт.</p><figure class="doc-image"><img src="'+r+'" alt="Паспорт (карточка) актива с историей операций"><figcaption>Паспорт (карточка) актива с историей операций</figcaption></figure><p>В нем отображается фотография, все заполненные характеристики, остаточная стоимость и <strong>индивидуальный журнал операций</strong> — полная история того, что происходило именно с этим предметом с момента его добавления.</p><h3 id="работа-с-имуществом" tabindex="-1">Работа с Имуществом <a class="header-anchor" href="#работа-с-имуществом" aria-label="Permalink to &quot;Работа с Имуществом&quot;">​</a></h3><ol><li><p><strong>Редактирование:</strong> Позволяет исправить опечатки в названии, изменить категорию или обновить фотографию.</p></li><li><p><strong>Переоценка и Модернизация:</strong> Если стоимость инструмента возросла (из-за модернизации или инфляции), используйте кнопку <strong>«Переоценить»</strong> в окне редактирования. Вы можете установить новую балансовую стоимость и новый остаточный срок службы. Обратите внимание: с момента проведения этой операции графики износа пересчитываются. Новая балансовая стоимость начинает амортизироваться строго <strong>от Даты переоценки</strong>, которая становится новой отправной точкой. Если переоценка связана с платным ремонтом или закупкой деталей для модернизации, отметьте опцию «Платное обслуживание / ремонт (расход в ДДС)» и укажите сумму — она автоматически спишется в расходы ДДС.</p><figure class="doc-image"><img src="'+s+'" alt="Модальное окно переоценки и модернизации актива"><figcaption>Модальное окно переоценки и модернизации актива</figcaption></figure></li><li><p><strong>Изменение статуса:</strong> Оборудование может находиться в статусах «В работе» или «В резерве» (временно не используется).</p></li><li><p><strong>Списание (Корзина):</strong> Удаление сломанного или утерянного актива с баланса. Исторические траты в ДДС сохранятся, но общая стоимость мастерской (Капитал) уменьшится.</p></li></ol><h3 id="работа-с-расходниками" tabindex="-1">Работа с Расходниками <a class="header-anchor" href="#работа-с-расходниками" aria-label="Permalink to &quot;Работа с Расходниками&quot;">​</a></h3><ol><li><p><strong>Пополнение (Докупить):</strong> При нажатии на иконку покупательской тележки (с плюсом) вы можете пополнить запасы расходника (например, докупить банку краски). Вы указываете сумму закупки и стоимость доставки. Программа прибавит эти суммы к общей стоимости расходника и проведет соответствующие списания в журнале ДДС.</p><figure class="doc-image"><img src="'+e+'" alt="Модальное окно пополнения расходника"><figcaption>Модальное окно пополнения расходника</figcaption></figure></li><li><p><strong>Архивация:</strong> Если вы больше не планируете закупать определенный расходный материал, его можно перенести в архив (иконка коробки). Он скроется из основного списка. Для просмотра архива и возможности восстановления нажмите кнопку со значком архива в верхней панели над таблицей.</p></li></ol><hr><h2 id="журнал-операции-мастерскои" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="8" height="4" x="8" y="2" rx="1" ry="1"></rect><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><path d="M12 11h4"></path><path d="M12 16h4"></path><path d="M8 11h.01"></path><path d="M8 16h.01"></path></svg> Журнал операций мастерской <a class="header-anchor" href="#журнал-операции-мастерскои" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;rect width=&quot;8&quot; height=&quot;4&quot; x=&quot;8&quot; y=&quot;2&quot; rx=&quot;1&quot; ry=&quot;1&quot;/&gt;&lt;path d=&quot;M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2&quot;/&gt;&lt;path d=&quot;M12 11h4&quot;/&gt;&lt;path d=&quot;M12 16h4&quot;/&gt;&lt;path d=&quot;M8 11h.01&quot;/&gt;&lt;path d=&quot;M8 16h.01&quot;/&gt;&lt;/svg&gt; Журнал операций мастерской&quot;">​</a></h2><p>Для обеспечения прозрачности учета в верхней панели инструментов расположена кнопка с иконкой часов — <strong>Журнал операций</strong>.</p><p>При ее нажатии открывается глобальный реестр всех действий в мастерской, отсортированный в хронологическом порядке. Журнал фиксирует:</p><ul><li>Внесение новых активов.</li><li>Факты редактирования (с указанием старых и новых значений).</li><li>Операции переоценки, пополнения расходников, архивации и списания имущества.</li></ul><hr><h2 id="поиск-сортировка-и-фильтрация" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon></svg> Поиск, сортировка и фильтрация <a class="header-anchor" href="#поиск-сортировка-и-фильтрация" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;polygon points=&quot;22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3&quot;/&gt;&lt;/svg&gt; Поиск, сортировка и фильтрация&quot;">​</a></h2><p>Для комфортной работы с большим парком оборудования предусмотрены мощные инструменты навигации:</p><ul><li><strong>Строка поиска:</strong> Позволяет мгновенно находить активы по названию, инвентарному номеру, категории или локации.</li><li><strong>Сортировка:</strong> Нажатие на заголовок любой колонки (например, «Остаток» или «Служит до») сортирует таблицу по возрастанию или убыванию.</li><li><strong>Фильтрация:</strong> При наведении курсора на заголовок колонки появляется иконка фильтра. С ее помощью можно выбрать конкретные статусы, категории или локации (используя удобные чекбоксы).</li><li><strong>Сброс:</strong> Если применены сортировки или фильтры, над таблицей появляются кнопки их быстрого сброса, возвращающие список к исходному виду.</li></ul><p>Таблица поддерживает пагинацию (постраничный вывод по 30 строк), что гарантирует плавную работу интерфейса даже при тысячах записей.</p><hr><h2 id="настроика-интерфеиса-вкладки" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="4" x2="20" y1="21" y2="14"></line><line x1="4" x2="20" y1="10" y2="3"></line><line x1="12" x2="12" y1="21" y2="12"></line><line x1="12" x2="12" y1="8" y2="3"></line><line x1="8" x2="16" y1="14" y2="14"></line><line x1="8" x2="16" y1="10" y2="10"></line></svg> Настройка интерфейса вкладки <a class="header-anchor" href="#настроика-интерфеиса-вкладки" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;line x1=&quot;4&quot; x2=&quot;20&quot; y1=&quot;21&quot; y2=&quot;14&quot;/&gt;&lt;line x1=&quot;4&quot; x2=&quot;20&quot; y1=&quot;10&quot; y2=&quot;3&quot;/&gt;&lt;line x1=&quot;12&quot; x2=&quot;12&quot; y1=&quot;21&quot; y2=&quot;12&quot;/&gt;&lt;line x1=&quot;12&quot; x2=&quot;12&quot; y1=&quot;8&quot; y2=&quot;3&quot;/&gt;&lt;line x1=&quot;8&quot; x2=&quot;16&quot; y1=&quot;14&quot; y2=&quot;14&quot;/&gt;&lt;line x1=&quot;8&quot; x2=&quot;16&quot; y1=&quot;10&quot; y2=&quot;10&quot;/&gt;&lt;/svg&gt; Настройка интерфейса вкладки&quot;">​</a></h2><p>Каждое производство уникально, поэтому внешний вид вкладки можно настроить под ваши потребности. Нажмите на иконку <strong>настроек (ползунки)</strong> в верхней панели:</p><ol><li><strong>Способ отображения статистики:</strong> Выберите, где будет выводиться аналитический блок — во всплывающем модальном окне или в виде закрепленной боковой колонки (колонка автоматически скрывается на экранах с низким разрешением).</li><li><strong>Отображение колонок:</strong> Вы можете скрыть ненужные столбцы отдельно для таблиц «Имущество» и «Расходники». Например, если вы не используете инвентарные номера, отключите их для экономии места.</li><li><strong>Отображение полей в блоке дополнительных параметров:</strong> Позволяет отключить лишние поля (локации, ссылки, фотографии) в форме добавления актива, чтобы ускорить процесс ввода данных.</li></ol><p><em>Примечание: управление справочниками «Категории» и «Локации» (переименование, добавление, удаление) осуществляется непосредственно из формы добавления актива при нажатии на иконку карандаша рядом с выпадающим списком.</em></p><hr><h2 id="статистика-мастерскои-аналитическии-блок" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" x2="12" y1="20" y2="10"></line><line x1="18" x2="18" y1="20" y2="4"></line><line x1="6" x2="6" y1="20" y2="16"></line></svg> Статистика мастерской (Аналитический блок) <a class="header-anchor" href="#статистика-мастерскои-аналитическии-блок" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;line x1=&quot;12&quot; x2=&quot;12&quot; y1=&quot;20&quot; y2=&quot;10&quot;/&gt;&lt;line x1=&quot;18&quot; x2=&quot;18&quot; y1=&quot;20&quot; y2=&quot;4&quot;/&gt;&lt;line x1=&quot;6&quot; x2=&quot;6&quot; y1=&quot;20&quot; y2=&quot;16&quot;/&gt;&lt;/svg&gt; Статистика мастерской (Аналитический блок)&quot;">​</a></h2><p>Нажмите на иконку графика в верхней панели, чтобы открыть аналитическую сводку по вашему имуществу. Панель агрегирует данные и выводит следующие показатели:</p><ol><li><strong>Остаточная стоимость имущества:</strong> Итоговая сумма (в рублях или выбранной валюте), отражающая текущую стоимость всех ваших физических активов с учетом накопленного износа.</li><li><strong>Текущий износ в месяц:</strong> Сумма, на которую ваш парк оборудования дешевеет каждые 30 дней.</li><li><strong>Структура капитала:</strong> Графические индикаторы (прогресс-бары), показывающие, в каких категориях сосредоточена наибольшая финансовая ценность (например, Оборудование — 75%, Инструменты — 25%).</li><li><strong>Сводка по парку:</strong> Общее количество объектов, число активов в работе и подробный перечень оборудования, выведенного в резерв.</li></ol><hr><h2 id="часто-задаваемые-вопросы-faq" tabindex="-1"><svg class="doc-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"></path><path d="M12 17h.01"></path></svg> Часто задаваемые вопросы (FAQ) <a class="header-anchor" href="#часто-задаваемые-вопросы-faq" aria-label="Permalink to &quot;&lt;svg class=&quot;doc-icon&quot; viewBox=&quot;0 0 24 24&quot; fill=&quot;none&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;&lt;circle cx=&quot;12&quot; cy=&quot;12&quot; r=&quot;10&quot;/&gt;&lt;path d=&quot;M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3&quot;/&gt;&lt;path d=&quot;M12 17h.01&quot;/&gt;&lt;/svg&gt; Часто задаваемые вопросы (FAQ)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что если я ошибся с оценкой срока службы?</summary><div class="faq-content"><p>Ничего страшного. Износ пересчитывается автоматически. Вы можете отредактировать срок в любой момент через функцию <strong>«Переоценить»</strong> в карточке актива. С даты переоценки программа начнет считать амортизацию по новым вводным, не нарушая прошлую финансовую историю.</p></div></details><details class="faq-item"><summary class="faq-summary">Как учесть изменение стоимости оборудования из-за инфляции?</summary><div class="faq-content"><p>Если рыночная стоимость вашего станка возросла, вы можете провести мягкую переоценку. Откройте карточку актива, нажмите <strong>«Переоценить»</strong> и укажите новую, более высокую балансовую стоимость. Капитал вашего бизнеса будет скорректирован в сторону увеличения, при этом касса (ДДС) не затронется, так как реальных денег вы не тратили.</p></div></details><details class="faq-item"><summary class="faq-summary">У меня не сохранились чеки на старые станки. Какую цену указывать?</summary><div class="faq-content"><p>Решение зависит от того, тратились ли на него средства бизнеса (ваши инвестиции):</p><ul><li><strong>Если станок покупался для мастерской (даже если точная цена забыта):</strong> Укажите его <em>первоначальную стоимость</em> (хотя бы примерную) и выберите в календаре историческую дату покупки в прошлом. Программа зафиксирует эту сумму как вашу инвестицию в кассовой книге (ДДС), а затем автоматически рассчитает износ за прошедшие годы, выведя корректный текущий остаток на сегодняшний день.<br><br><em>💡 <strong>Нюанс с простаивающим оборудованием:</strong> Если станок всё это время лежал на складе, не использовался, и вы хотите начать считать его износ только с текущего момента, поступите так: сначала внесите его исторической датой (чтобы зафиксировать прошлую инвестицию в ДДС), а затем сразу откройте его карточку и сделайте <strong>«Переоценку»</strong>. Укажите ту же стоимость, полный срок службы и <strong>сегодняшнюю дату</strong>. Это перенесет точку отсчета амортизации на сегодня, сохранив корректную финансовую историю.</em></li><li><strong>Если станок подарен или принесен из личного пользования (деньги бизнеса не тратились):</strong> Оцените его по <em>текущей рыночной стоимости</em> на сегодняшний день, выберите сегодняшний день в календаре, укажите оставшийся срок службы и <strong>обязательно включите опцию «Без учёта затрат в ДДС»</strong>.</li></ul></div></details></div>',73)])])}const y=n(q,[["render",g]]);export{x as __pageData,y as default};
